void truncate(Poly&z,int degree){Poly p;ulong ex[3];fmpq_t c;fmpq_init(c);for(int j=0;j<fmpq_mpoly_length(z.p,ctx);j++){fmpq_mpoly_get_term_exp_ui(ex,z.p,j,ctx);if(ex[2]>(ulong)degree)continue;fmpq_mpoly_get_term_coeff_fmpq(c,z.p,j,ctx);fmpq_mpoly_push_term_fmpq_ui(p.p,c,ex,ctx);}fmpq_mpoly_sort_terms(p.p,ctx);z=p;fmpq_clear(c);}
int main(int argc,char**argv){assert(argc==5);int precision=stoi(argv[4]);ifstream in(argv[1]);ofstream out(argv[2]),o0(argv[3]);assert(in&&out&&o0);auto start=chrono::steady_clock::now();fmpq_mpoly_ctx_init(ctx,3,ORD_LEX);{int n,m;in>>n>>m;vector<vector<Poly>>A(n,vector<Poly>(m));for(auto&r:A)for(auto&p:r)read(in,p,3);const char*var[]={"a","e","delta"};Poly h,s;assert(!fmpq_mpoly_set_str_pretty(h.p,"50*a+18*e^2-9*e-2",var,ctx));assert(!fmpq_mpoly_set_str_pretty(s.p,"delta-60*e+40",var,ctx));int maxd=0;vector<int>rd(n);for(int i=0;i<n;i++)for(auto&p:A[i])rd[i]=max<int>(rd[i],fmpq_mpoly_degree_si(p.p,2,ctx));for(int d:rd)maxd=max(maxd,d);vector<Poly>hp(maxd+1);fmpq_mpoly_one(hp[0].p,ctx);for(int d=1;d<=maxd;d++)fmpq_mpoly_mul(hp[d].p,hp[d-1].p,h.p,ctx);out<<n<<' '<<m<<'\n';o0<<n<<' '<<m<<'\n';ulong ex[3];fmpq_t c;fmpq_init(c);long terms=0;for(int i=0;i<n;i++){for(auto&p:A[i]){int d=max<long>(0,fmpq_mpoly_degree_si(p.p,2,ctx));vector<Poly>co(d+1);for(int k=0;k<fmpq_mpoly_length(p.p,ctx);k++){fmpq_mpoly_get_term_exp_ui(ex,p.p,k,ctx);int degree=ex[2];ex[2]=0;fmpq_mpoly_get_term_coeff_fmpq(c,p.p,k,ctx);fmpq_mpoly_push_term_fmpq_ui(co[degree].p,c,ex,ctx);}for(auto&q:co)fmpq_mpoly_sort_terms(q.p,ctx);Poly z=co[d],tmp,add;for(int k=d-1;k>=0;k--){fmpq_mpoly_mul(tmp.p,z.p,s.p,ctx);fmpq_mpoly_mul(add.p,co[k].p,hp[d-k].p,ctx);fmpq_mpoly_add(z.p,tmp.p,add.p,ctx);truncate(z,precision);}fmpq_mpoly_mul(tmp.p,z.p,hp[rd[i]-d].p,ctx);z=tmp;write(out,z,3);terms+=fmpq_mpoly_length(z.p,ctx);Poly zero;for(int k=0;k<fmpq_mpoly_length(z.p,ctx);k++){fmpq_mpoly_get_term_exp_ui(ex,z.p,k,ctx);if(ex[2])continue;fmpq_mpoly_get_term_coeff_fmpq(c,z.p,k,ctx);fmpq_mpoly_push_term_fmpq_ui(zero.p,c,ex,ctx);}fmpq_mpoly_sort_terms(zero.p,ctx);write(o0,zero,2);}}fmpq_clear(c);out.flush();o0.flush();assert(out.good()&&o0.good());cerr<<"SHIFT_PASS TERMS "<<terms<<" SEC "<<chrono::duration<double>(chrono::steady_clock::now()-start).count()<<'\n';}fmpq_mpoly_ctx_clear(ctx);flint_cleanup();}
